const svg=$('#tableaux-svg'), out=$('#tableaux-out'), pick=$('#tableaux-shape');
const nextBtn=$('#tableaux-next');
const W=600,H=300, cell=46, ox=210, oy=40;
// each shape: lambda + a small list of candidate fillings (row-major arrays of arrays)
const SHAPES={
  '22':{ lam:[2,2], fills:[
    [[1,2],[3,4]],   // valid SYT
    [[1,3],[2,4]],   // valid SYT
    [[1,1],[2,3]],   // valid SSYT, not standard (repeat)
    [[1,2],[1,3]],   // INVALID: column 1 has 1 then 1 (not strict)
    [[2,1],[3,4]]    // INVALID: row 1 not weakly increasing
  ]},
  '32':{ lam:[3,2], fills:[
    [[1,2,3],[4,5]],   // valid SYT
    [[1,1,2],[2,3]],   // valid SSYT
    [[1,3,5],[2,4]],   // valid SYT
    [[1,1,1],[1,2]],   // INVALID: column 1 has 1 then 1
    [[1,2,2],[2,3]]    // valid SSYT (col1 1<2, col2 2<3)
  ]},
  '311':{ lam:[3,1,1], fills:[
    [[1,2,3],[4],[5]],   // valid SYT
    [[1,2,4],[3],[5]],   // valid SYT
    [[1,2,2],[2],[3]],   // valid SSYT
    [[1,2,3],[1],[2]],   // INVALID: column 1 has 1 then 1
    [[1,1,2],[2],[2]]    // INVALID: column 1 is 1,2,2 — 2 is not < 2 (columns must be STRICTLY increasing)
  ]}
};
let cur='22', idx=0;
function conj(lam){ const m=lam[0]; const c=[]; for(let j=0;j<m;j++){ let k=0; for(const r of lam) if(r>j) k++; c.push(k);} return c; }
function validate(lam,fill){
  let rowOK=true, colOK=true;
  // rows weakly increasing
  for(let i=0;i<lam.length;i++){ for(let j=1;j<lam[i];j++){ if(fill[i][j] < fill[i][j-1]) rowOK=false; } }
  // columns strictly increasing
  const m=lam[0];
  for(let j=0;j<m;j++){ for(let i=1;i<lam.length;i++){ if(lam[i]>j && lam[i-1]>j){ if(!(fill[i][j] > fill[i-1][j])) colOK=false; } } }
  return {rowOK,colOK};
}
function isStandard(lam,fill){ const n=lam.reduce((a,b)=>a+b,0); const seen=new Set(); let strictRow=true, strictCol=true;
  for(let i=0;i<lam.length;i++) for(let j=0;j<lam[i];j++) seen.add(fill[i][j]);
  if(seen.size!==n) return false;
  for(let v=1;v<=n;v++) if(!seen.has(v)) return false;
  for(let i=0;i<lam.length;i++) for(let j=1;j<lam[i];j++) if(!(fill[i][j] > fill[i][j-1])) strictRow=false;
  return strictRow; }
function render(){
  const sh=SHAPES[cur], lam=sh.lam, fill=sh.fills[idx];
  svg.innerHTML='';
  const {rowOK,colOK}=validate(lam,fill);
  const ok = rowOK && colOK;
  const std = ok && isStandard(lam,fill);
  const ncells = lam.reduce((a,b)=>a+b,0);
  // draw cells
  for(let i=0;i<lam.length;i++){ for(let j=0;j<lam[i];j++){
    const x=ox+j*cell, y=oy+i*cell;
    svg.appendChild(SVG('rect',{x,y,width:cell-3,height:cell-3,rx:5,
      fill: ok? 'var(--panel)' : 'var(--panel2)',
      stroke: ok? 'var(--green)' : 'var(--pink)', 'stroke-width':1.8}));
    const t=SVG('text',{x:x+(cell-3)/2,y:y+(cell-3)/2+5,'text-anchor':'middle','font-size':18,fill:'var(--ink)','font-weight':600});
    t.textContent=fill[i][j]; svg.appendChild(t);
  } }
  const cap=SVG('text',{x:20,y:26,'font-size':12,fill:'var(--mute)'}); cap.textContent='shape  '+lam.join(',')+'   conjugate  '+conj(lam).join(',')+'   ('+ncells+' cells)'; svg.appendChild(cap);
  const verdict = ok ? (std? 'valid STANDARD tableau (uses 1..'+ncells+' once, strict rows and columns)' : 'valid SEMISTANDARD tableau (rows weak, columns strict)')
                     : ('NOT semistandard: '+(!rowOK? 'a row fails to weakly increase' : 'a column fails to strictly increase'));
  out.textContent =
    'filling '+(idx+1)+' of '+sh.fills.length+':  rows '+(rowOK?'weakly increase ✓':'FAIL ✗')+'   columns '+(colOK?'strictly increase ✓':'FAIL ✗')+'\n'+verdict;
}
pick.addEventListener('change',()=>{ cur=pick.value; idx=0; render(); });
nextBtn.addEventListener('click',()=>{ const sh=SHAPES[cur]; idx=(idx+1)%sh.fills.length; render(); });
render();

const svg=$('#hook-svg'), out=$('#hook-out'), pick=$('#hook-shape');
const W=600,H=300, cell=46, ox=200, oy=40;
const SHAPES={ '22':[2,2], '31':[3,1], '32':[3,2], '221':[2,2,1] };
let cur='22';
function fact(n){ let r=1; for(let i=2;i<=n;i++) r*=i; return r; }
function conj(lam){ const m=lam[0]; const c=[]; for(let j=0;j<m;j++){ let k=0; for(const r of lam) if(r>j) k++; c.push(k);} return c; }
function hookOf(lam,i,j){ const cj=conj(lam); const arm=lam[i]-j-1; const leg=cj[j]-i-1; return arm+leg+1; }
// brute-force count of SYT: fill 1..n into cells so each cell's left and up neighbours are already filled
function countSYT(lam){ const n=lam.reduce((a,b)=>a+b,0); const cells=[]; for(let i=0;i<lam.length;i++) for(let j=0;j<lam[i];j++) cells.push([i,j]); const T={}; const key=(i,j)=>i+','+j; let cnt=0; (function rec(v){ if(v>n){cnt++;return;} for(const [i,j] of cells){ if(T[key(i,j)]) continue; if(j>0 && !T[key(i,j-1)]) continue; if(i>0 && !T[key(i-1,j)]) continue; T[key(i,j)]=v; rec(v+1); delete T[key(i,j)]; } })(1); return cnt; }
function render(){
  const lam=SHAPES[cur]; const n=lam.reduce((a,b)=>a+b,0);
  svg.innerHTML='';
  let prod=1; const hookStrs=[];
  for(let i=0;i<lam.length;i++){ for(let j=0;j<lam[i];j++){
    const h=hookOf(lam,i,j); prod*=h; hookStrs.push(h);
    const x=ox+j*cell, y=oy+i*cell;
    svg.appendChild(SVG('rect',{x,y,width:cell-3,height:cell-3,rx:5,fill:'var(--panel)',stroke:'var(--violet)','stroke-width':1.8}));
    const t=SVG('text',{x:x+(cell-3)/2,y:y+(cell-3)/2+6,'text-anchor':'middle','font-size':18,fill:'var(--yellow)','font-weight':700});
    t.textContent=h; svg.appendChild(t);
  } }
  const formula=fact(n)/prod; const direct=countSYT(lam); const agree=(formula===direct);
  const cap=SVG('text',{x:20,y:26,'font-size':12,fill:'var(--mute)'}); cap.textContent='shape '+lam.join(',')+'   (each cell shows its hook length = arm + leg + 1)'; svg.appendChild(cap);
  out.textContent =
    'hook lengths: '+hookStrs.join(' · ')+'    product = '+prod+'\n'+
    'hook length formula:  f^λ = '+n+'! / '+prod+' = '+fact(n)+' / '+prod+' = '+formula+'\n'+
    'direct count of standard tableaux = '+direct+'   '+(agree?'✓ they agree':'✗ MISMATCH');
}
pick.addEventListener('change',()=>{ cur=pick.value; render(); });
render();

const svg=$('#symmetric-svg'), out=$('#symmetric-out'), pick=$('#symmetric-basis');
const lamSl=$('#symmetric-lam'), lamL=$('#symmetric-lam-lbl');
const N=3; // x1,x2,x3
const PARTS={ 1:[1], 2:[2], 3:[1,1], 4:[2,1] };
let cur='e';
// a monomial is an exponent vector [a1,a2,a3]; multiply by tensoring sums of monomials
function key(v){ return v.join(','); }
function addPoly(poly, vec, coef){ const k=key(vec); poly[k]=(poly[k]||0)+coef; if(poly[k]===0) delete poly[k]; }
function mulPoly(A,B){ const C={}; for(const ka in A){ const va=ka.split(',').map(Number); for(const kb in B){ const vb=kb.split(',').map(Number); const v=va.map((x,i)=>x+vb[i]); addPoly(C,v,A[ka]*B[kb]); } } return C; }
// single-part generators
function e_k(k){ const P={}; // squarefree degree-k: choose k distinct indices
  const idx=[...Array(N).keys()]; const combos=[]; (function ch(start,acc){ if(acc.length===k){combos.push(acc.slice());return;} for(let i=start;i<N;i++){acc.push(i); ch(i+1,acc); acc.pop();} })(0,[]);
  for(const c of combos){ const v=Array(N).fill(0); c.forEach(i=>v[i]=1); addPoly(P,v,1);} return P; }
function h_k(k){ const P={}; // all degree-k monomials (with repetition)
  (function gen(start,rem,v){ if(rem===0){ addPoly(P,v.slice(),1); return; } for(let i=start;i<N;i++){ v[i]++; gen(i,rem-1,v); v[i]--; } })(0,k,Array(N).fill(0)); return P; }
function p_k(k){ const P={}; for(let i=0;i<N;i++){ const v=Array(N).fill(0); v[i]=k; addPoly(P,v,1);} return P; }
function gen(basis,k){ return basis==='e'? e_k(k) : basis==='h'? h_k(k) : p_k(k); }
function expandLambda(basis,lam){ let P={ [key(Array(N).fill(0))]:1 }; for(const part of lam) P=mulPoly(P,gen(basis,part)); return P; }
function monoStr(vec){ const parts=[]; for(let i=0;i<N;i++){ if(vec[i]===0) continue; parts.push('x'+(i+1)+(vec[i]>1?'^'+vec[i]:'')); } return parts.length? parts.join('') : '1'; }
function render(){
  const sym = +lamSl.value; const lam=PARTS[sym];
  lamL.textContent='λ = ('+lam.join(',')+')';
  const sub = (cur==='e'?'e':cur==='h'?'h':'p');
  const P = expandLambda(cur,lam);
  // sort monomials by descending exponent vector
  const entries = Object.entries(P).map(([k,c])=>[k.split(',').map(Number),c]).sort((a,b)=>{ for(let i=0;i<N;i++){ if(b[0][i]!==a[0][i]) return b[0][i]-a[0][i]; } return 0; });
  svg.innerHTML='';
  const head=SVG('text',{x:W2(),y:60,'text-anchor':'middle','font-size':22,fill:'var(--yellow)','font-weight':700}); head.textContent=sub+'_('+lam.join(',')+')  in  x1, x2, x3'; svg.appendChild(head);
  const nterms = entries.length, ndeg = lam.reduce((a,b)=>a+b,0);
  const info=SVG('text',{x:W2(),y:110,'text-anchor':'middle','font-size':14,fill:'var(--mute)'}); info.textContent='degree '+ndeg+',  '+nterms+' distinct monomials'; svg.appendChild(info);
  // build a readable polynomial string
  const str = entries.map(([v,c])=> (c===1?'':c)+monoStr(v)).join(' + ');
  const poly=SVG('text',{x:W2(),y:160,'text-anchor':'middle','font-size':15,fill:'var(--cyan)'}); poly.textContent = str.length>78? '(see readout)' : str; svg.appendChild(poly);
  let note='';
  if(cur==='e' && sym===2) note='note: e_(2) = x1x2 + x1x3 + x2x3 has only squarefree terms';
  else if(cur==='h' && sym===2) note='note: h_(2) adds the squares x1^2, x2^2, x3^2 that e_(2) omits';
  else if(cur==='p') note='note: p_k = sum of pure k-th powers; products give cross terms';
  out.textContent =
    sub+'_('+lam.join(',')+')(x1,x2,x3) = '+str+'\n'+
    'degree '+ndeg+',  '+nterms+' monomials'+(note? '\n'+note : '');
}
function W2(){ return 300; }
pick.addEventListener('change',()=>{ cur=pick.value; render(); });
lamSl.addEventListener('input',render);
render();

const svg=$('#schur-svg'), out=$('#schur-out'), pick=$('#schur-shape');
const varSl=$('#schur-vars'), varL=$('#schur-vars-lbl');
const SHAPES={ '21':[2,1], '2':[2], '11':[1,1], '22':[2,2] };
let cur='21';
function ssytList(lam,N){ const cells=[]; for(let i=0;i<lam.length;i++) for(let j=0;j<lam[i];j++) cells.push([i,j]); const res=[]; const T={}; const key=(i,j)=>i+','+j;
  (function rec(idx){ if(idx===cells.length){ const snap={}; for(const k in T) snap[k]=T[k]; res.push(snap); return; } const [i,j]=cells[idx]; for(let v=1;v<=N;v++){ if(j>0 && T[key(i,j-1)]>v) continue; if(i>0 && !(T[key(i-1,j)]<v)) continue; T[key(i,j)]=v; rec(idx+1); delete T[key(i,j)]; } })(0); return res; }
function content(t,N){ const c=Array(N).fill(0); for(const k in t) c[t[k]-1]++; return c; }
function monoStr(vec){ const parts=[]; for(let i=0;i<vec.length;i++){ if(vec[i]===0) continue; parts.push('x'+(i+1)+(vec[i]>1?'^'+vec[i]:'')); } return parts.length? parts.join('') : '1'; }
function render(){
  const lam=SHAPES[cur]; const N=+varSl.value; varL.textContent='N = '+N;
  const ts=ssytList(lam,N);
  // monomial multiplicities = Kostka numbers
  const mono={}; for(const t of ts){ const c=content(t,N); const k=c.join(','); mono[k]=(mono[k]||0)+1; }
  const entries=Object.entries(mono).map(([k,c])=>[k.split(',').map(Number),c]).sort((a,b)=>{ for(let i=0;i<N;i++){ if(b[0][i]!==a[0][i]) return b[0][i]-a[0][i]; } return 0; });
  svg.innerHTML='';
  // draw up to 4 example tableaux
  const showN=Math.min(4,ts.length); const cell=34, gap=24; const totW=showN*(lam[0]*cell+gap); let sx=(600-totW)/2 + 10;
  for(let s=0;s<showN;s++){ const t=ts[s]; const baseX=sx+s*(lam[0]*cell+gap), baseY=40;
    for(let i=0;i<lam.length;i++){ for(let j=0;j<lam[i];j++){ const x=baseX+j*cell, y=baseY+i*cell;
      svg.appendChild(SVG('rect',{x,y,width:cell-2,height:cell-2,rx:4,fill:'var(--panel)',stroke:'var(--violet)','stroke-width':1.5}));
      const tx=SVG('text',{x:x+(cell-2)/2,y:y+(cell-2)/2+5,'text-anchor':'middle','font-size':15,fill:'var(--ink)','font-weight':600}); tx.textContent=t[i+','+j]; svg.appendChild(tx);
    } } }
  const cap=SVG('text',{x:300,y:24,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); cap.textContent='shape '+lam.join(',')+'   entries in {1..'+N+'}   ('+ts.length+' SSYT'+(ts.length>showN?', first '+showN+' shown':'')+')'; svg.appendChild(cap);
  const total=SVG('text',{x:300,y:200,'text-anchor':'middle','font-size':13,fill:'var(--cyan)'}); total.textContent='s_'+lam.join('')+'(1'+(N===3?',1,1':',1')+') = '+ts.length+'  (set all x_i = 1)'; svg.appendChild(total);
  const str=entries.map(([v,c])=> (c===1?'':c)+monoStr(v)).join(' + ');
  out.textContent =
    's_('+lam.join(',')+')(x1..x'+N+') = '+str+'\n'+
    'total SSYT = '+ts.length+';  a coefficient k > 1 is the Kostka number K(λ, that content)';
}
pick.addEventListener('change',()=>{ cur=pick.value; render(); });
varSl.addEventListener('input',render);
render();

const svg=$('#rsk-svg'), out=$('#rsk-out');
const permSl=$('#rsk-perm'), permL=$('#rsk-perm-lbl');
const stepSl=$('#rsk-step'), stepL=$('#rsk-step-lbl');
const PRESETS=[ [3,1,4,2], [2,4,1,3], [1,2,3,4], [4,3,2,5,1] ];
// row-insert x into P (array of rows); return new P and the row index where a cell was created
function rowInsert(P,x){ const Q2=P.map(r=>r.slice()); let r=0, cur=x; while(true){ if(!Q2[r]) Q2[r]=[]; const row=Q2[r]; let pos=row.findIndex(e=>e>cur); if(pos===-1){ row.push(cur); return {P:Q2, row:r, col:row.length-1}; } else { const tmp=row[pos]; row[pos]=cur; cur=tmp; r++; } } }
// longest increasing subsequence length
function lis(arr){ const tails=[]; for(const x of arr){ let lo=0,hi=tails.length; while(lo<hi){ const m=(lo+hi)>>1; if(tails[m]<x) lo=m+1; else hi=m; } tails[lo]=x; } return tails.length; }
function drawTab(svg,rows,baseX,baseY,title,accent){ const cell=32; const t=SVG('text',{x:baseX,y:baseY-10,'font-size':13,fill:accent,'font-weight':700}); t.textContent=title; svg.appendChild(t);
  for(let i=0;i<rows.length;i++){ for(let j=0;j<rows[i].length;j++){ const x=baseX+j*cell, y=baseY+i*cell;
    svg.appendChild(SVG('rect',{x,y,width:cell-2,height:cell-2,rx:4,fill:'var(--panel)',stroke:accent,'stroke-width':1.5}));
    const tx=SVG('text',{x:x+(cell-2)/2,y:y+(cell-2)/2+5,'text-anchor':'middle','font-size':14,fill:'var(--ink)','font-weight':600}); tx.textContent=rows[i][j]; svg.appendChild(tx);
  } } }
function render(){
  const pi=+permSl.value; const w=PRESETS[pi]; const n=w.length;
  permL.textContent='w = '+w.join(' ');
  stepSl.max=n; let k=+stepSl.value; if(k>n){ k=n; stepSl.value=n; }
  stepL.textContent=k+' / '+n;
  // run RSK for first k insertions
  let P=[], Q=[];
  for(let s=0;s<k;s++){ const {P:np,row,col}=rowInsert(P,w[s]); P=np; if(!Q[row]) Q[row]=[]; Q[row][col]=s+1; }
  svg.innerHTML='';
  const cap=SVG('text',{x:300,y:24,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); cap.textContent='permutation '+w.map((v,i)=> i<k? '['+v+']' : v).join(' ')+'   (bracketed = inserted)'; svg.appendChild(cap);
  drawTab(svg,P,90,70,'P (insertion)','var(--cyan)');
  drawTab(svg,Q,360,70,'Q (recording)','var(--pink)');
  const shape=P.map(r=>r.length);
  let msg='inserted '+k+' of '+n+' values: '+w.slice(0,k).join(', ')+(k<n?'   (move the step slider to continue)':'');
  msg+='\nP shape = ('+shape.join(',')+')'+(k===n? '   — equals Q shape (RSK pairs share a shape)':'');
  if(k===n){ msg+='\nlongest increasing subsequence of w has length '+lis(w)+' = length of the first row of P (Schensted)'; }
  out.textContent=msg;
}
permSl.addEventListener('input',()=>{ stepSl.value=PRESETS[+permSl.value].length; render(); });
stepSl.addEventListener('input',render);
render();

const svg=$('#rep-svg'), out=$('#rep-out');
const nSl=$('#rep-n'), nL=$('#rep-n-lbl');
const W=600,H=320;
function fact(n){ let r=1; for(let i=2;i<=n;i++) r*=i; return r; }
function parts(n,max){ max=max||n; if(n===0) return [[]]; const res=[]; for(let k=Math.min(n,max);k>=1;k--){ for(const t of parts(n-k,k)) res.push([k,...t]); } return res; }
function conj(lam){ const m=lam[0]; const c=[]; for(let j=0;j<m;j++){ let k=0; for(const r of lam) if(r>j) k++; c.push(k);} return c; }
function nSYT(lam){ const n=lam.reduce((a,b)=>a+b,0); const cj=conj(lam); let prod=1; for(let i=0;i<lam.length;i++){ for(let j=0;j<lam[i];j++){ const arm=lam[i]-j-1, leg=cj[j]-i-1; prod*=(arm+leg+1); } } return fact(n)/prod; }
function render(){
  const n=+nSl.value; nL.textContent='n = '+n;
  const ps=parts(n); const dims=ps.map(nSYT);
  const maxD=Math.max(...dims); const sumSq=dims.reduce((a,d)=>a+d*d,0);
  svg.innerHTML='';
  const padL=50, padR=20, padT=50, padB=70; const plotW=W-padL-padR, plotH=H-padT-padB;
  const bw=plotW/ps.length;
  for(let i=0;i<ps.length;i++){ const d=dims[i]; const h=plotH*d/maxD; const x=padL+i*bw, y=padT+plotH-h;
    svg.appendChild(SVG('rect',{x:x+bw*0.12,y,width:bw*0.76,height:h,rx:4,fill:'var(--cyan)',opacity:0.85,stroke:'var(--line)'}));
    const dl=SVG('text',{x:x+bw/2,y:y-6,'text-anchor':'middle','font-size':12,fill:'var(--yellow)','font-weight':700}); dl.textContent=d; svg.appendChild(dl);
    const pl=SVG('text',{x:x+bw/2,y:padT+plotH+18,'text-anchor':'middle','font-size':11,fill:'var(--mute)'}); pl.textContent='('+ps[i].join(',')+')'; svg.appendChild(pl);
    const sq=SVG('text',{x:x+bw/2,y:padT+plotH+34,'text-anchor':'middle','font-size':10,fill:'var(--mute)'}); sq.textContent=d+'²='+(d*d); svg.appendChild(sq);
  }
  svg.appendChild(SVG('line',{x1:padL,y1:padT+plotH,x2:W-padR,y2:padT+plotH,stroke:'var(--line)','stroke-width':1.2}));
  const cap=SVG('text',{x:300,y:26,'text-anchor':'middle','font-size':13,fill:'var(--mute)'}); cap.textContent='dim of each irreducible of S'+n+'  =  #SYT(λ)  over the '+ps.length+' partitions λ ⊢ '+n; svg.appendChild(cap);
  const ok=(sumSq===fact(n));
  out.textContent =
    'partitions of '+n+': '+ps.map(p=>'('+p.join(',')+')').join(', ')+'\n'+
    'dimensions f^λ: '+dims.join(', ')+'\n'+
    'Σ (dim)² = '+dims.map(d=>d+'²').join(' + ')+' = '+sumSq+'   and   '+n+'! = '+fact(n)+'   '+(ok?'✓ equal':'✗ MISMATCH');
}
nSl.addEventListener('input',render);
render();
